    99  v_buff_size Utils::calcUnescapedStringSize(const char* data, v_buff_size size, v_int64& errorCode, v_buff_size& errorPosition) {
   100    errorCode = 0;
   101    v_buff_size result = 0;
   102    v_buff_size i = 0;
   103
   104    while (i < size) {
   105      v_char8 a = static_cast<v_char8>(data[i]);
   106      if(a == '\\'){
   107
   108        if(i + 1 == size){
   109          errorCode = ERROR_CODE_INVALID_ESCAPED_CHAR;
   110          errorPosition = i;
   111          return 0;
   112        }
   113
   114        v_char8 b = static_cast<v_char8>(data[i + 1]);
   115
   116        if(b == '"' || b == '\\' || b == '/' || b == 'b' || b == 'f' || b == 'n' || b == 'r' || b == 't'){
   117          result += 1;
   118          i += 2;
   119        } else if(b == 'u'){
   120
   121          if(i + 6 > size){
   122            errorCode = ERROR_CODE_INVALID_ESCAPED_CHAR;
   123            errorPosition = i;
   124            return 0;
   125          }
   126
   127          if(data[i + 2] == '+') { // not JSON standard case
   128            if(i + 11 > size){
   129              errorCode = ERROR_CODE_INVALID_ESCAPED_CHAR;
   130              errorPosition = i;
   131              return 0;
   132            }
   133            v_uint32 code;
   134            errorCode = encoding::Hex::readUInt32(&data[i + 3], code);
   135            if(errorCode != 0){
   136              errorPosition = i + 3;
   137              return 0;
   138            }
   139            i += 11;
   140            result += encoding::Unicode::getUtf8CharSequenceLengthForCode(code);
   141          } else {
   142            v_uint16 code;
   143            errorCode = encoding::Hex::readUInt16(&data[i + 2], code);
   144            if(errorCode != 0){
   145              errorPosition = i + 2;
   146              return 0;
   147            }
   148
   149            if(code >= 0xD800 && code <= 0xDBFF){
   150              if(i + 12 > size){
   151                errorCode = ERROR_CODE_INVALID_SURROGATE_PAIR;
   152                errorPosition = i;
   153                return 0;
   154              }
   155              v_uint16 low;
   156              errorCode = encoding::Hex::readUInt16(&data[i + 8], low);
   157              if(errorCode != 0){
   158                errorPosition = i + 8;
   159                return 0;
   160              }
